package com.haucheng.erp.service;
import com.haucheng.erp.auth.CurrentUserContext; import com.haucheng.erp.dto.*; import com.haucheng.erp.entity.SysPermission; import com.haucheng.erp.entity.SysRole; import com.haucheng.erp.exception.BusinessException; import com.haucheng.erp.mapper.RoleMapper; import com.haucheng.erp.vo.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class RoleService {
 private static final Set<String> BUILT_IN_CODES=Set.of("SYSTEM_ADMIN","WAREHOUSE_ADMIN","DEPARTMENT_MANAGER","EMPLOYEE","MANAGEMENT");
 private final RoleMapper mapper; private final OperationLogService operationLog;
 public List<RoleView> getAll(){ List<RoleView> list=mapper.selectAll(); list.forEach(x->x.setPermissionIds(mapper.selectPermissionIds(x.getId()))); return list; }
 public List<RoleBriefView> getOptions(){ return mapper.selectOptions(); }
 public RoleView getById(Long id){ RoleView v=mapper.selectViewById(id); if(v==null) throw BusinessException.notFound("角色不存在"); v.setPermissionIds(mapper.selectPermissionIds(id)); return v; }
 @Transactional public RoleView create(RoleRequest r){ String c=r.getRoleCode().trim(),n=r.getRoleName().trim(); ensureScopeAllowed(r.getDataScope()); unique(c,n,null); SysRole e=build(r,c,n); mapper.insert(e); operationLog.record("ROLE_CREATE",String.valueOf(e.getId()),"创建角色"); return getById(e.getId()); }
 @Transactional public RoleView update(Long id,RoleRequest r){ SysRole old=require(id); String c=r.getRoleCode().trim(),n=r.getRoleName().trim(); if(!c.equals(old.getRoleCode())) throw BusinessException.badRequest("角色编码创建后不能修改"); ensureScopeAllowed(r.getDataScope()); unique(c,n,id); SysRole e=build(r,c,n); e.setId(id); mapper.update(e); operationLog.record("ROLE_UPDATE",String.valueOf(id),"修改角色"); return getById(id); }
 @Transactional public void updateStatus(Long id,Boolean status){ SysRole role=require(id); if(!status&&"SYSTEM_ADMIN".equals(role.getRoleCode())) throw BusinessException.conflict("系统管理员角色不能停用"); mapper.updateStatus(id,status); operationLog.record(status?"ROLE_ENABLE":"ROLE_DISABLE",String.valueOf(id),status?"启用角色":"停用角色"); }
 @Transactional public void delete(Long id){ SysRole role=require(id); if(BUILT_IN_CODES.contains(role.getRoleCode())) throw BusinessException.conflict("内置角色不能删除"); if(mapper.countUsers(id)>0) throw BusinessException.conflict("角色已分配给用户，不能删除"); mapper.deletePermissions(id); mapper.deleteById(id); operationLog.record("ROLE_DELETE",String.valueOf(id),"删除角色"); }
 public List<PermissionTreeView> permissionTree(){ Map<Long,PermissionTreeView> m=new LinkedHashMap<>(); for(SysPermission p:mapper.selectPermissions()){ PermissionTreeView v=new PermissionTreeView(); v.setId(p.getId());v.setParentId(p.getParentId());v.setPermissionCode(p.getPermissionCode());v.setPermissionName(p.getPermissionName());v.setPermissionType(p.getPermissionType());v.setRoutePath(p.getRoutePath());v.setSortOrder(p.getSortOrder());v.setStatus(p.getStatus());m.put(v.getId(),v);} List<PermissionTreeView> roots=new ArrayList<>(); for(PermissionTreeView v:m.values()){ PermissionTreeView parent=v.getParentId()==null?null:m.get(v.getParentId()); if(parent==null) roots.add(v); else parent.getChildren().add(v);} return roots; }
 @Transactional public RoleView replacePermissions(Long id,RolePermissionRequest r){ SysRole role=require(id); if("SYSTEM_ADMIN".equals(role.getRoleCode())) throw BusinessException.conflict("系统管理员角色权限不能修改"); List<Long> ids=new ArrayList<>(new LinkedHashSet<>(r.getPermissionIds())); if(ids.size()!=r.getPermissionIds().size()) throw BusinessException.badRequest("权限不能重复选择"); if(!ids.isEmpty()&&mapper.countActivePermissionIds(ids)!=ids.size()) throw BusinessException.badRequest("包含不存在或停用的权限"); if(!isSystemAdmin()){ Set<String> granted=new HashSet<>(CurrentUserContext.require().getPermissions()); for(Long permissionId:ids){ SysPermission permission=mapper.selectPermission(permissionId); if(permission==null||!granted.contains(permission.getPermissionCode())) throw BusinessException.forbidden("不能授予超出自身范围的权限"); } } mapper.deletePermissions(id); ids.forEach(x->mapper.insertPermission(id,x)); operationLog.record("ROLE_PERMISSIONS_UPDATE",String.valueOf(id),"修改角色权限"); return getById(id); }
 public boolean isSystemAdmin(){ return CurrentUserContext.get()!=null&&CurrentUserContext.get().getRoles().contains("SYSTEM_ADMIN"); }
 public void ensureScopeAllowed(String scope){ if(scope==null||isSystemAdmin()) return; String own=CurrentUserContext.require().getDataScope(); if(scopeRank(scope)>scopeRank(own)) throw BusinessException.forbidden("不能设置超出自身范围的数据权限"); }
 private int scopeRank(String scope){return "ALL".equals(scope)?3:"DEPARTMENT".equals(scope)?2:1;}
 private SysRole build(RoleRequest r,String c,String n){ SysRole e=new SysRole();e.setRoleCode(c);e.setRoleName(n);e.setDescription(r.getDescription());e.setDataScope(r.getDataScope()==null?"SELF":r.getDataScope());e.setStatus(r.getStatus()==null||r.getStatus());return e; }
 private SysRole require(Long id){SysRole e=mapper.selectById(id);if(e==null)throw BusinessException.notFound("角色不存在");return e;} private void unique(String c,String n,Long id){if(mapper.countByCode(c,id)>0)throw BusinessException.conflict("角色编码已存在");if(mapper.countByName(n,id)>0)throw BusinessException.conflict("角色名称已存在");}
}
